func testReceitasToManyAddOpRecContratoEntidadeTipos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Receitas
	var b, c, d, e ContratoEntidadeTipo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, receitasDBTypes, false, strmangle.SetComplement(receitasPrimaryKeyColumns, receitasColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ContratoEntidadeTipo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, contratoEntidadeTipoDBTypes, false, strmangle.SetComplement(contratoEntidadeTipoPrimaryKeyColumns, contratoEntidadeTipoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ContratoEntidadeTipo{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddRecContratoEntidadeTipos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.RecID, first.RecID) {
			t.Error("foreign key was wrong value", a.RecID, first.RecID)
		}
		if !queries.Equal(a.RecID, second.RecID) {
			t.Error("foreign key was wrong value", a.RecID, second.RecID)
		}

		if first.R.Rec != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Rec != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.RecContratoEntidadeTipos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.RecContratoEntidadeTipos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.RecContratoEntidadeTipos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

