func testReceitasToOnePlanoContasFinanceiroUsingPCF(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Receitas
	var foreign PlanoContasFinanceiro

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, receitasDBTypes, false, receitasColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Receitas struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, planoContasFinanceiroDBTypes, false, planoContasFinanceiroColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize PlanoContasFinanceiro struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.PCFID = foreign.PCFID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.PCF().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.PCFID != foreign.PCFID {
		t.Errorf("want: %v, got %v", foreign.PCFID, check.PCFID)
	}

	ranAfterSelectHook := false
	AddPlanoContasFinanceiroHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *PlanoContasFinanceiro) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := ReceitasSlice{&local}
	if err = local.L.LoadPCF(ctx, tx, false, (*[]*Receitas)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.PCF == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.PCF = nil
	if err = local.L.LoadPCF(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.PCF == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

func testReceitasToOneSetOpPlanoContasFinanceiroUsingPCF(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Receitas
	var b, c PlanoContasFinanceiro

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, receitasDBTypes, false, strmangle.SetComplement(receitasPrimaryKeyColumns, receitasColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, planoContasFinanceiroDBTypes, false, strmangle.SetComplement(planoContasFinanceiroPrimaryKeyColumns, planoContasFinanceiroColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, planoContasFinanceiroDBTypes, false, strmangle.SetComplement(planoContasFinanceiroPrimaryKeyColumns, planoContasFinanceiroColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*PlanoContasFinanceiro{&b, &c} {
		err = a.SetPCF(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.PCF != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.PCFReceitas[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.PCFID != x.PCFID {
			t.Error("foreign key was wrong value", a.PCFID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.PCFID))
		reflect.Indirect(reflect.ValueOf(&a.PCFID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.PCFID != x.PCFID {
			t.Error("foreign key was wrong value", a.PCFID, x.PCFID)
		}
	}
}

